/**
 * native-tool-aliases
 *
 * Registers Claude-style capitalized native tool aliases (Read/Edit/Write/Grep/Find/Ls)
 * by wrapping the upstream lowercase tool factories. Also owns the WebFetch/WebSearch
 * marker tools (claude-bridge native server tools that throw on local execute).
 *
 * Lifts these tool definitions out of pi-mono-fork core so the fork can stay closer
 * to upstream. The hardcoded tool-name references in `agent-session.ts` and `sdk.ts`
 * (defaultActiveToolNames, CLAUDE_BRIDGE_NATIVE_TOOL_NAMES) resolve to these
 * extension-provided tools at session startup via the runtime tool registry.
 *
 * Alias pattern: call the upstream factory with its native `toolName`/`label`
 * options, then register the result as always loaded for cache-stable aliases.
 */

import {
  createEditToolDefinition,
  createFindToolDefinition,
  createGrepToolDefinition,
  createLsToolDefinition,
  createReadToolDefinition,
  createWriteToolDefinition,
  type ExtensionAPI,
} from "@earendil-works/pi-coding-agent";
import { Container, Text } from "@earendil-works/pi-tui";
import { type Static, Type } from "typebox";

// --- Capitalized aliases for upstream tools ------------------------------------

// --- WebFetch / WebSearch marker tools -----------------------------------------
//
// These are native Anthropic/Claude server tools. The provider intercepts the
// tool call before local execute(); local execute() never legitimately runs.

const webFetchSchema = Type.Object({
  allowed_domains: Type.Optional(Type.Array(Type.String({ description: "Only allow fetching from these domains" }))),
  blocked_domains: Type.Optional(Type.Array(Type.String({ description: "Never fetch from these domains" }))),
  max_content_tokens: Type.Optional(
    Type.Number({ description: "Approximate maximum tokens used for fetched web page text content" }),
  ),
  use_cache: Type.Optional(
    Type.Boolean({
      description:
        "Whether to use cached content. Set false only when the user explicitly requests fresh content or rapidly-changing sources.",
    }),
  ),
});

type WebFetchInput = Static<typeof webFetchSchema>;

const webSearchSchema = Type.Object({
  query: Type.String({ description: "Search query" }),
  allowed_domains: Type.Optional(Type.Array(Type.String({ description: "Only allow results from these domains" }))),
  blocked_domains: Type.Optional(Type.Array(Type.String({ description: "Never return results from these domains" }))),
});

type WebSearchInput = Static<typeof webSearchSchema>;

const WEBFETCH_UNSUPPORTED = "WebFetch is only available with the claude-bridge provider";
const WEBFETCH_LOCAL = "WebFetch is a native Anthropic/Claude provider tool and should not execute locally";
const WEBSEARCH_UNSUPPORTED = "WebSearch is only available with the claude-bridge provider";
const WEBSEARCH_LOCAL = "WebSearch is a native Anthropic/Claude provider tool and should not execute locally";

function normalizeWebFetchInput(args: unknown): WebFetchInput {
  return args && typeof args === "object" ? (args as WebFetchInput) : {};
}

function normalizeWebSearchInput(args: unknown): WebSearchInput {
  const input = args && typeof args === "object" ? (args as WebSearchInput) : ({ query: "" } as WebSearchInput);
  if (input.allowed_domains?.length && input.blocked_domains?.length) {
    throw new Error("WebSearch accepts either allowed_domains or blocked_domains, not both");
  }
  return input;
}

function registerWebFetch(pi: ExtensionAPI) {
  for (const name of ["WebFetch", "web_fetch"] as const) {
    pi.registerTool({
      name,
      label: name,
      description:
        "Fetch web page content using Anthropic/Claude's native web_fetch server tool. Only available for claude-bridge models.",
      promptSnippet: "Fetch web page content using Anthropic/Claude's native web_fetch server tool.",
      parameters: webFetchSchema,
      prepareArguments: normalizeWebFetchInput,
      async execute(_toolCallId, _params, _signal, _onUpdate, ctx) {
        if (ctx.model?.provider !== "claude-bridge") throw new Error(WEBFETCH_UNSUPPORTED);
        throw new Error(WEBFETCH_LOCAL);
      },
      renderCall(args, theme) {
        const opts: string[] = [];
        if (args?.allowed_domains?.length) opts.push(`allow ${args.allowed_domains.join(", ")}`);
        if (args?.blocked_domains?.length) opts.push(`block ${args.blocked_domains.join(", ")}`);
        if (args?.use_cache === false) opts.push("fresh");
        const suffix = opts.length ? ` ${theme.fg("toolOutput", `(${opts.join("; ")})`)}` : "";
        return new Text(`${theme.fg("toolTitle", theme.bold(name))}${suffix}`, 0, 0);
      },
      renderResult(result, { expanded }, theme) {
        if (!expanded) return new Container();
        const block = result.content.find((item) => item.type === "text");
        const text = block?.type === "text" ? block.text : "(no output)";
        return new Text(theme.fg("dim", text), 0, 0);
      },
    });
  }
}

function registerWebSearch(pi: ExtensionAPI) {
  for (const name of ["WebSearch", "web_search"] as const) {
    pi.registerTool({
      name,
      label: name,
      description:
        "Search the web using Anthropic/Claude's native web_search server tool. Only available for claude-bridge models.",
      promptSnippet: "Search the web using Anthropic/Claude's native web_search server tool.",
      parameters: webSearchSchema,
      prepareArguments: normalizeWebSearchInput,
      async execute(_toolCallId, _params, _signal, _onUpdate, ctx) {
        if (ctx.model?.provider !== "claude-bridge") throw new Error(WEBSEARCH_UNSUPPORTED);
        throw new Error(WEBSEARCH_LOCAL);
      },
      renderCall(args, theme) {
        const query = typeof args?.query === "string" ? args.query : "";
        const shown = query.length > 90 ? `${query.slice(0, 87)}...` : query;
        let text = theme.fg("toolTitle", theme.bold(name));
        if (shown) text += ` ${theme.fg("accent", `"${shown}"`)}`;
        return new Text(text, 0, 0);
      },
      renderResult(result, { expanded }, theme) {
        if (!expanded) return new Container();
        const block = result.content.find((item) => item.type === "text");
        const text = block?.type === "text" ? block.text : "(no output)";
        return new Text(theme.fg("dim", text), 0, 0);
      },
    });
  }
}

export default function nativeToolAliasesExtension(pi: ExtensionAPI) {
  const cwd = process.cwd();
  // alwaysLoad: true keeps these tools cache-stable across
  // _refreshToolRegistry calls. After PR #1C removed Read/Edit/Write/Grep/Find/Ls
  // from core's allToolNames, the builtin-preservation gate no longer covers
  // them — alwaysLoad: true takes its place.
  pi.registerTool({
    ...createReadToolDefinition(cwd, { toolName: "Read", label: "Read" }),
    alwaysLoad: true,
  });
  pi.registerTool({
    ...createEditToolDefinition(cwd, { toolName: "Edit", label: "Edit" }),
    alwaysLoad: true,
  });
  pi.registerTool({
    ...createWriteToolDefinition(cwd, { toolName: "Write", label: "Write" }),
    alwaysLoad: true,
  });
  pi.registerTool({
    ...createGrepToolDefinition(cwd, { toolName: "Grep", label: "Grep" }),
    alwaysLoad: true,
  });
  pi.registerTool({
    ...createFindToolDefinition(cwd, { toolName: "Find", label: "Find" }),
    alwaysLoad: true,
  });
  pi.registerTool({
    ...createLsToolDefinition(cwd, { toolName: "Ls", label: "Ls" }),
    alwaysLoad: true,
  });
  registerWebFetch(pi);
  registerWebSearch(pi);
}
